# Generates the human-readable report from analysis tables; no models refitted.
.libPaths(c('work/R-library',.libPaths()))
readtab <- function(n) read.delim(paste0('outputs/tables/',n,'.tsv'),check.names=FALSE)
esc <- function(x) {x<-gsub('&','&amp;',as.character(x),fixed=TRUE); x<-gsub('<','&lt;',x,fixed=TRUE); gsub('>','&gt;',x,fixed=TRUE)}
tbl <- function(x) paste0('<table><thead><tr>',paste0('<th>',esc(names(x)),'</th>',collapse=''),'</tr></thead><tbody>',paste(apply(x,1,function(r) paste0('<tr>',paste0('<td>',esc(r),'</td>',collapse=''),'</tr>')),collapse=''),'</tbody></table>')
fmt <- function(x,d=2) formatC(x,format='f',digits=d,decimal.mark=',')
model <- readtab('model_results'); flow<-readtab('participant_flow'); miss<-readtab('missing_65plus'); prev<-readtab('weighted_prevalence'); diag<-readtab('model_diagnostics')
labels<-c(M0='M0: nur Schluckbeschwerden',M1='M1: + Alter, Geschlecht',M2='M2: + soziale und gesundheitliche Merkmale',M3_primary='M3: + Treffen und Telefon/Video (primär)',M4_participation='M4: + Gottesdienst und Vereine',M3_available='M3: alle für M3 vollständigen Fälle',M3_depression_matched='M3: Vergleich auf Depressionsstichprobe',M3_depression='M3: + depressive Gefühle',M3_broad_endpoint='M3: breiter Einsamkeitsendpunkt',M3_no_proxy='M3: ohne Proxy-Interviews',M3_logistic='M3: logistische Sensitivität (OR)',M3_severity='M3: Schwere (sekundär)')
mr<-data.frame(Modell=unname(labels[model$model]),Vergleich=ifelse(model$term=='swallow','ja versus nein',sub('severity','',model$term)),Maß=model$measure,Schätzer=fmt(model$estimate),KI_95=paste0(fmt(model$lower),'–',fmt(model$upper)),N=model$n,Ereignisse=model$events,check.names=FALSE)
flabel<-c('Alle Erwachsenen','Numerisches Alter ab 65','Zusätzlich über AGE65 bestätigt','Alle bestätigten Personen ab 65','Exposition und Endpunkt gültig','Vollständige Angaben für M3','Gemeinsame Stichprobe M0–M4','Zusätzlich Depression gültig','Gemeinsame Stichprobe ohne Proxy','Schwereanalyse vollständig')
ft<-data.frame(Schritt=flabel,N=flow$n)
mt<-data.frame(Variable=miss$variable,Fehlend=miss$missing,Prozent=fmt(miss$percent_missing))
pt<-data.frame(Gruppe=c('Alle ab 65: Schluckbeschwerden','Alle ab 65: häufig einsam','Ohne Schluckbeschwerden: häufig einsam','Mit Schluckbeschwerden: häufig einsam','Ohne Beschwerden, gemeinsame Modellstichprobe','Mit Beschwerden, gemeinsame Modellstichprobe'),N_gültig=prev$n_valid,Ereignisse=prev$n_events,Prozent=fmt(100*prev$prevalence),KI_95=paste0(fmt(100*prev$lower),'–',fmt(100*prev$upper)),check.names=FALSE)
mapping<-data.frame(Variable=c('VSLSWYR_A','VSLSWDIF_A','LONELY_A','SUPPORT_A','SCONNECT1_A','SCONNECT2_A','SCONNECT3_A','SCONNECT4_A','AGEP_A','AGE65','SEX_A','EDUCP_A','POVRATTC_A','IMPNUM_A','IMPINCFLG_A','MARITAL_A','PCNT18UPTC','PCNTLT18TC','DIFF_A','HEARINGDF_A','STREV_A','DEPFREQ_A','PROXYFLAG_A','WTFA_A','PSTRAT','PPSU'),
Verwendung=c('1 ja, 2 nein; 7/8/9 fehlend','Nur VSLSWYR_A=1: 1 wenig, 3 mittel, 2 stark; strukturelle Skips getrennt','1/2 häufig, 3/4/5 nicht häufig; Sensitivität 1/2/3 versus 4/5','1 immer, 2 meistens, 3 manchmal, 4 selten, 5 nie; nur deskriptiv','Treffen außerhalb Haushalt pro Woche: 0 <1, 1=1–2, 2=3–4, 3 >=5','Telefon/Video außerhalb Haushalt pro Woche: gleiche Codes wie SCONNECT1','Gottesdienste/Jahr: 0=0, 1=1–3, 2=4–11, 3 >=12','Vereinstreffen/Jahr: 0=0/keine Mitgliedschaft, 1=1–3, 2=4–11, 3 >=12','65–74, 75–84, 85+; 97/98/99 fehlend','Nur bei unbekanntem numerischen Alter: 2 bestätigt >=65; kein Ersatz für genaue Altersgruppe','1 männlich, 2 weiblich; 7/8/9 fehlend','1–2 unter Highschool; 3–4 Highschool/GED; 5–7 College/Associate; 8–10 Bachelor+','<1, 1–<2, 2–<4, >=4; alle zehn offiziellen Imputationen','1–10; getrennte Analysen, anschließend Rubin-Pooling','0 berichtet; 1/2 imputiert; nicht als beobachtet ausgeben','1/2 verheiratet oder zusammenlebend, 3 weder noch','Zusammen mit PCNTLT18TC: allein, wenn 1 Erwachsener und 0 Kinder','0 Kinder für Definition des Alleinlebens','1 keine, 2 etwas, 3/4 starke/volle Mobilitätseinschränkung','1 keine, 2 etwas, 3/4 starke/volle Hörschwierigkeit','1 jemals Schlaganfall mitgeteilt, 2 nein','1/2 täglich/wöchentlich, 3/4/5 seltener/nie; Sensitivität','1 Proxy, 2 kein Proxy','Finales jährliches Erwachsenengewicht','Public-use Varianzstratum','Public-use PSU, innerhalb Stratum verschachtelt'),stringsAsFactors=FALSE)
x<-pdftools::pdf_text('work/docs/adult-codebook.pdf')
mapping$Codebook_Seite<-vapply(mapping$Variable,function(v) {i<-grep(paste0('Variable: +',v,'[[:space:]]'),x); if(length(i)) paste(i,collapse=', ') else 'Einkommens-Zusatzdatei'},character(1))
write.table(mapping,'outputs/tables/variable_mapping.tsv',sep='\t',quote=FALSE,row.names=FALSE,fileEncoding='UTF-8')
selected<-unique(unlist(lapply(mapping$Variable,function(v) grep(paste0('Variable: +',v,'[[:space:]]'),x))))
writeLines(x[selected],'work/docs/relevant_codebook_pages.txt',useBytes=TRUE)
contact_summary<-do.call(rbind,lapply(1:4,function(j) {a<-readtab(paste0('contact',j,'cells_complete')); data.frame(Kontakt=paste0('SCONNECT',j,'_A'),Kleinste_Zelle=min(a$Freq),Zellen_unter_10=sum(a$Freq<10),Nullzellen=sum(a$Freq==0))}))
severity<-readtab('severity_outcome_complete')
html<-c('<!doctype html><html lang="de"><meta charset="utf-8"><title>NHIS 2025 – Schluckbeschwerden und Einsamkeit</title><style>body{font:16px/1.55 system-ui,Arial,sans-serif;color:#182b3a;max-width:1120px;margin:40px auto;padding:0 24px}h1{line-height:1.15}h2{margin-top:2.2em;border-bottom:2px solid #dce8e8;padding-bottom:8px}table{border-collapse:collapse;width:100%;font-size:14px;margin:18px 0}td,th{text-align:left;border-bottom:1px solid #dce1e6;padding:8px;vertical-align:top}th{background:#edf4f4}tr:nth-child(even){background:#f8fafb}.lead{background:#e9f3f1;padding:20px;border-left:5px solid #257c70}.note{color:#53616c}a{color:#006e82}@media print{body{font-size:11pt;margin:0;max-width:none}table{font-size:9pt}tr{break-inside:avoid}}</style><body>',
'<p class="note">Projekt 2 · Daten- und Statistikbericht · 6. November 2026 · NHIS Public-use 2025</p><h1>Schluckbeschwerden und Einsamkeit ab 65 Jahren</h1>',
'<div class="lead"><strong>Die Hauptanalyse ist machbar und zeigt eine adjustierte Assoziation.</strong> Häufige Einsamkeit ist bei Personen mit selbstberichteten Schluckbeschwerden auch unter Berücksichtigung der gemessenen persönlichen und telefonischen Kontaktfrequenz häufiger: PR 1,83 (95%-KI 1,42–2,38). Dies ist eine Querschnittsassoziation, kein Nachweis eines ursächlichen Effekts.</div>',
'<h2>1. Datenstand und Qualitätssicherung</h2><p>Die offizielle CDC-Erwachsenendatei umfasst 24.215 Datensätze und 577 Variablen. Verwendet wurden adult25csv.zip, adultinc25csv.zip, das Erwachsenen-Codebook (29. Juli 2026), die Survey Description (August 2026) und die Einkommensdokumentation (Mai 2026). Downloads und SHA-256-Prüfsummen sind im Startskript festgehalten. Drei Gesamtfrequenzen wurden gegen das Codebook geprüft: Schluckbeschwerden ja (1.463), Einsamkeit immer (692) und starke Schluckbeschwerden (264). Schlüssel sind eindeutig, Gewichte positiv, und pro Person liegen genau zehn Einkommensimputationen vor.</p>',
'<p>Der Analyseplan wurde nach Sichtung der offiziellen Dokumentation, aber vor eigenen Kreuztabellen und Regressionen gespeichert. Die Codebook-Häufigkeiten waren bereits bekannt; es handelt sich nicht um eine externe Präregistrierung. Die Software R 4.6.0 nutzt survey und mitools. Die Pakete wurden für R 4.6.1 gebaut; beim Laden erschien ein entsprechender Versionshinweis, jedoch kein Analysefehler. Die anfänglichen Windows-Locale-Hinweise beeinflussen keine numerischen Definitionen. Paketversionen stehen in der Sitzungsdatei.</p>',
'<h2>2. Population und Machbarkeit</h2>',tbl(ft),
'<p>AGEP_A hat Vorrang. Die 24 zusätzlichen Personen mit unbekanntem numerischen Alter und AGE65=2 gehen nur in die deskriptive Population ein. Die gemeinsame Modellstichprobe umfasst 95,3 % aller bestätigten Personen ab 65. Von 674 Personen mit Schluckbeschwerden berichten 82 häufige Einsamkeit, von 7.420 ohne Beschwerden 347. Die kleinste Zelle der Exposition-Endpunkt-Tabelle beträgt 82. Es liegen 429 Ereignisse für 29 Nicht-Intercept-Parameter im umfangreichsten Hauptfolgemodell vor (14,8 pro Parameter). Damit werden die vorab gesetzten pragmatischen Prüfgrenzen erfüllt; eine Garantie gegen Modellinstabilität ist dies nicht.</p>',tbl(readtab('exposure_outcome_complete')),
'<p>Das vollständige Survey-Design enthält 46 Strata und 608 PSUs (562 Freiheitsgrade). In der gemeinsamen Analysedomäne sind 607 PSUs vertreten (561 Freiheitsgrade). Das Design wurde vor der Einschränkung auf ältere bzw. vollständige Fälle auf allen Erwachsenen definiert. Im Gesamtdesign gibt es keine Einzel-PSU-Strata.</p>',
'<h2>3. Fehlende Angaben und Skip-Logik</h2>',tbl(mt),
'<p>Alle Missing-Anteile beziehen sich auf 8.492 Personen. Die Schwerevariable in dieser Tabelle ist die abgeleitete Vier-Kategorien-Exposition: strukturelle Leereinträge bei verneinten Beschwerden sind darin als „keine Beschwerden“ enthalten. In der Rohvariable fehlen 7.555 Schwereantworten strukturell bei verneinten Beschwerden; weitere 248 liegen bei unbekannter Exposition. Unter den 689 Personen mit Beschwerden ist eine Schwereantwort ungültig. Keine Person ohne bestätigte Beschwerden hat eine ausgefüllte Schwereantwort. 7/8/9 bzw. 97/98/99 werden variablenspezifisch als fehlend behandelt, nie als gültige Kategorien.</p>',
'<p>Unter den 398 ausgeschlossenen Personen sind nur 150 Expositions- und 148 Endpunktantworten verfügbar. Deren gewichtete Häufigkeiten (10,45 % Beschwerden; 5,68 % häufige Einsamkeit) sind unpräzise und erlauben keine Entwarnung hinsichtlich Selektionsbias. Die vollständige-Fälle-Analyse imputiert keine Exposition, Einsamkeit oder übrigen Kovariaten. Für Einkommen werden hingegen alle zehn offiziellen Imputationen genutzt.</p>',
'<h2>4. Gewichtete deskriptive Ergebnisse</h2>',tbl(pt),
'<p>Endpunkt: „immer“ oder „meistens“ einsam (LONELY_A=1/2), gegenüber manchmal/selten/nie. Exposition: Schluckbeschwerden in den vergangenen zwölf Monaten. Gewichte, Strata und PSUs werden berücksichtigt; Prävalenzintervalle beruhen auf einer designbasierten Logit-Transformation. Die Nenner unterscheiden sich wegen fehlender Antworten. Die angegebenen Prozentwerte sind gewichtete Schätzungen, die Ereigniszahlen ungewichtet.</p>',
'<h2>5. Modellfolge und Sensitivitäten</h2>',tbl(mr),
'<p>M0–M4 verwenden dieselben 8.094 Personen. M1 ergänzt Alter und Geschlecht; M2 zusätzlich Bildung, Familienarmutsquotient, Partnerschaft, Alleinleben, Mobilität, Hören und Schlaganfallanamnese. M3 ergänzt persönliche Treffen und Telefon-/Videokontakte außerhalb des Haushalts. M4 ergänzt Gottesdienst- und Vereinsbesuche. Alle Kontaktvariablen werden als kategoriale Faktoren verwendet. Einkommensadjustierte Ergebnisse werden aus zehn getrennten Survey-Modellen mit Rubin-Regeln und endlichen Freiheitsgraden gepoolt. PR sind Prävalenzverhältnisse, keine Risiken für zukünftige Ereignisse; die gesonderte logistische Sensitivität liefert eine OR.</p>',
'<p>Der primäre Schätzer verändert sich durch die zusätzliche Berücksichtigung von Gottesdienst- und Vereinsbesuchen kaum. Bei Kontrolle depressiver Gefühle fällt er auf PR 1,47 (1,14–1,89); der korrekte Vergleich auf denselben 8.055 Fällen beträgt ohne Depression 1,84 (1,42–2,38). Eine Abschwächung belegt keine Mediation. Bei einem breiteren Einsamkeitsendpunkt liegt das PR bei 1,25 (1,10–1,41); ohne Proxy-Interviews bei 1,99 (1,55–2,56). Die ergänzenden Analysen sind nicht für multiples Testen korrigiert.</p>',
'<h2>6. Schwere und dünn besetzte Zellen</h2>',tbl(severity),
'<p>Die Referenz ist jeweils „keine Schluckbeschwerden“. Die nach den Codes korrekt geordneten Kategorien zeigen ansteigende Schätzer, aber die stark betroffene Gruppe enthält nur 22 Einsamkeitsereignisse. Deshalb sekundär und vorsichtig interpretieren; kein vorab definierter Trendtest und keine Aussage über einen kausalen Dosis-Wirkungs-Verlauf.</p>',tbl(contact_summary),
'<p>Die Kontakt-Kreuztabellen beziehen sich auf Exposition × vier Kontaktkategorien × Endpunkt in der gemeinsamen Stichprobe. Persönliche Treffen enthalten eine Zelle mit acht Ereignissen bei Exponierten. Die Hauptmodelle schätzen keine Exposition-Kontakt-Interaktionen; für belastbare stratumsspezifische Effekte reichen einzelne Zellen nicht aus. Rohzellen sind als Machbarkeitsprüfung gedacht, nicht als eigenständige verlässliche Populationsschätzungen.</p>',
'<h2>7. Modelldiagnostik und Grenzen</h2><p>Alle 120 Modellanpassungen (zwölf Modelle über zehn Imputationen) konvergierten; Koeffizienten und Kovarianzmatrizen sind endlich. Das primäre Poisson-Modell ergibt angepasste Werte zwischen 0,005 und 0,728. In der Depressionssensitivität und beim breiteren Endpunkt liegen einzelne angepasste Werte über 1 (Maxima 1,210 und 1,595). Das ist eine Grenze der modifizierten Poisson-Mittelwertfunktion: Diese Modelle dürfen nicht als individuelle Wahrscheinlichkeitsmodelle verwendet werden. Die vollständige Diagnostiktabelle dokumentiert die Werte. Die Hauptanalyse ist davon nicht betroffen; für einen finalen Artikel sollte die Angemessenheit der Sensitivitätsmodelle zusätzlich fachlich geprüft werden.</p>',
'<p>„Vergleichbare Kontaktfrequenz“ bedeutet hier statistische Adjustierung für grobe berichtete Kategorien. Qualität der Beziehungen, Kontakte innerhalb des Haushalts und weitere gemeinsame Ursachen können unzureichend erfasst sein. Schluckbeschwerden sind selbstberichtet und nicht klinisch diagnostiziert. Einsamkeit wird mit einem Einzelitem ohne festen Zwölfmonatsbezug gemessen; die Zeitbezüge der Variablen unterscheiden sich. Die Querschnittsdaten klären weder zeitliche Richtung noch Ursache. Mobilität, Depression und soziale Kontakte könnten teilweise auch Folgen der Beschwerden sein. Complete-case-Selektion, Survey-Nonresponse, Topkodierung des Alters und Ausschluss institutionalisierter Personen begrenzen die Übertragbarkeit.</p>',
'<p>Die Analyse liefert einen reproduzierbaren empirischen Ausgangspunkt, keine Neuheits- oder Publikationsgarantie. Vor Manuskriptabschluss bleiben fachliche Prüfung der Kovariatenwahl, vollständige NCHS-Präzisionsbewertung für alle publizierten Untergruppen, Missing-Data-Sensitivität und Abgleich mit der separat bearbeiteten Literatur sinnvoll. Die Ergebnisse sind nicht als klinische Handlungsempfehlung zu verwenden.</p>',
'<h2>8. Variablenmapping</h2>',tbl(mapping),
'<p class="note">Seiten sind PDF-Seiten des offiziellen Erwachsenen-Codebooks. HHX ist der Verknüpfungsschlüssel. Die allgemeinen Missing-Codes gelten nicht pauschal für jede Variable; gültige Werte werden im Analyseskript explizit zugelassen. SUPPORT_A ist in den Rohfrequenzen dokumentiert und wird nicht als Hauptkovariate verwendet.</p>',
'<h2>9. Reproduktion und Dateien</h2><p><a href="01_Analyseplan.txt">Analyseplan</a> · <a href="02_Analyse.R">vollständiges R-Skript</a> · <a href="04_Download_und_Start.ps1">Download und Start</a> · <a href="03_R_SessionInfo.txt">R-Sitzung</a> · <a href="tables/model_results.tsv">Modellergebnisse</a> · <a href="tables/variable_mapping.tsv">Variablenmapping</a></p><p>Das Startskript aus PowerShell ausführen; bei Bedarf den Rscript-Pfad als Parameter angeben. Es prüft die Dateiversionen, richtet Pakete unter work/R-library ein und startet Analyse und Bericht. Tabellen liegen unter outputs/tables, Rohdaten und Zwischenstände unter work. Der Bericht ist ohne externe Schriftarten oder Dienste lesbar. Paketversionen sind dokumentiert, die Installation aus CRAN jedoch nicht eingefroren; für bitgenaue langfristige Reproduktion müssen die dokumentierten Binärpakete archiviert werden.</p>',
'<h2>Offizielle Quellen</h2><ul><li><a href="https://www.cdc.gov/nchs/nhis/documentation/2025-nhis.html">CDC: NHIS 2025 Dokumentation und Daten</a></li><li><a href="https://ftp.cdc.gov/pub/Health_Statistics/NCHS/Dataset_Documentation/NHIS/2025/adult-codebook.pdf">Erwachsenen-Codebook</a></li><li><a href="https://ftp.cdc.gov/pub/Health_Statistics/NCHS/Dataset_Documentation/NHIS/2025/srvydesc-508.pdf">Survey Description, insbesondere S. 49 und 72–74</a></li><li><a href="https://ftp.cdc.gov/pub/Health_Statistics/NCHS/Dataset_Documentation/NHIS/2025/NHIS2025-imputation-techdoc-508.pdf">Multiple Einkommensimputation: Methoden</a></li></ul></body></html>')
writeLines(enc2utf8(html),'outputs/00_Machbarkeit_und_Ergebnisse.html',useBytes=TRUE)
